        aFoldValue |= static_cast<std::uint32_t>(aSourceLaneD[aIndexD]) << 8U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);
        aFoldF[aIndex] = static_cast<std::uint8_t>(aFoldValue);
